def transform(grid):
    from collections import deque

    h, w = len(grid), len(grid[0])

    # Find the connected zero-valued canvas.
    seen = set()
    best = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == 0 and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            if len(comp) > len(best):
                best = comp

    r0 = min(r for r, c in best)
    r1 = max(r for r, c in best)
    c0 = min(c for r, c in best)
    c1 = max(c for r, c in best)
    out = [[0] * (c1 - c0 + 1) for _ in range(r1 - r0 + 1)]

    # Colored cells within the canvas are the markers to replicate.
    markers = {}
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            color = grid[r][c]
            if color != 0:
                markers[color] = (r - r0, c - c0)

    # Count outside objects of each color using 8-connectivity.
    counts = {}
    seen = set()
    for r in range(h):
        for c in range(w):
            if (r0 <= r <= r1 and c0 <= c <= c1) or grid[r][c] == 0 or (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            while q:
                y, x = q.popleft()
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        if dy == 0 and dx == 0:
                            continue
                        ny, nx = y + dy, x + dx
                        if (0 <= ny < h and 0 <= nx < w and
                                not (r0 <= ny <= r1 and c0 <= nx <= c1) and
                                grid[ny][nx] == color and (ny, nx) not in seen):
                            seen.add((ny, nx))
                            q.append((ny, nx))
            counts[color] = counts.get(color, 0) + 1

    for color, (r, c) in markers.items():
        for k in range(counts.get(color, 0)):
            x = c + 2 * k
            if x < len(out[0]):
                out[r][x] = color

    return out
